const PIT_CAM_LEAD = 20;   // metres before the box
const PIT_CAM_EXIT = 10;   // metres after leaving the box

function pitCamRequested() {
  const pit = race?.pit;
  if (!pit || race.state === 'finished') return false;
  if (pit.phase === 'servicing') return true;
  const { boxDistance } = pitMetrics();
  if (pit.phase === 'driving-in') return boxDistance - pit.routeProgress <= PIT_CAM_LEAD;
  if (pit.phase === 'driving-out') return pit.routeProgress - boxDistance <= PIT_CAM_EXIT;
  return false;
}

// A fixed broadcast-style overhead shot of the player's own box. The stance is
// taken from the box itself (not the car) so the car drives into a still frame,
// then holds while the crew work, then releases once the car has pulled away.
function pitBoxCameraShot() {
  const box = race.world.playerPitBox;
  const yaw = box.yaw;
  const laneX = Math.sin(yaw), laneZ = Math.cos(yaw);
  const garageX = Math.cos(yaw), garageZ = -Math.sin(yaw);
  const aspect = race.camera.aspect || 1.7;
  const portrait = aspect < 1;
  // Portrait screens need a wider stance to keep the whole car in frame.
  const back = portrait ? 11.5 : 6.2;
  const height = portrait ? 19.5 : 18.5;
  const fov = 34;
  const px = box.x - garageX * back - laneX * 0.9;
  const pz = box.z - garageZ * back - laneZ * 0.9;
  camPitPos.set(px, height, pz);
  camPitLook.set(
    box.x + garageX * 0.6 + laneX * 0.5,
    0.5,
    box.z + garageZ * 0.6 + laneZ * 0.5
  );
  return { pos: camPitPos, look: camPitLook, fov };
}
```

