import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright', 'package.json'));
const { chromium } = require('playwright');
import { readFileSync } from 'node:fs';

const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const launchOptions = { ...config.browser.launchOptions, headless: false };
delete launchOptions.channel;
if (process.env.DISPLAY == null) process.env.DISPLAY = ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch(launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
page.on('pageerror', (e) => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3002/?demo=race&go=1', { waitUntil: 'load' });
await page.waitForFunction(() => window.__apex?.race?.state === 'racing', null, { timeout: 30000 });
await page.waitForTimeout(500);

await page.evaluate(() => {
  const r = window.__apex.race;
  r.pit.serviceDuration = 0.7;
  const boxDist = r.world.pitBoxDistance;
  const d = boxDist - 2.2;
  const route = r.world.pitRoute;
  const i = Math.min(route.length - 2, Math.floor(d / 5));
  const t = d / 5 - i;
  const a = route[i], b = route[i + 1];
  const x = a.x + (b.x - a.x) * t, z = a.z + (b.z - a.z) * t;
  let tx = a.tx + (b.tx - a.tx) * t, tz = a.tz + (b.tz - a.tz) * t;
  const len = Math.hypot(tx, tz) || 1;
  tx /= len; tz /= len;
  const yaw = Math.atan2(tx, tz);
  const k = Math.min(1, 2.2 / 36);
  const offset = r.world.pitBoxLateral * (1 - k * k * (3 - 2 * k));
  r.pit.phase = 'driving-in';
  r.pit.routeProgress = d;
  r.pit.entryProgress = 0;
  r.player.progressDist = d;
  r.player.pos.x = x + Math.cos(yaw) * offset;
  r.player.pos.z = z - Math.sin(yaw) * offset;
  r.player.yaw = yaw;
  r.player.vel.x = 0; r.player.vel.z = 0; r.player.vLong = 1.5;
  r.player.lastIndex = r.locator.lastIndex;
});

await page.waitForFunction(() => window.__apex.race.pit.phase === 'servicing', null, { timeout: 60000 });
console.log('dock ok', await page.evaluate(() => ({ blend: __apex.race.pitCamBlend, y: __apex.race.camera.position.y })));
await page.waitForFunction(() => window.__apex.race.pit.phase === 'driving-out', null, { timeout: 60000 });
await page.waitForFunction(() => window.__apex.race.pit.routeProgress > window.__apex.race.world.pitBoxDistance + 3, null, { timeout: 30000 });
console.log('leaving', await page.evaluate(() => ({
  phase: __apex.race.pit.phase,
  route: __apex.race.pit.routeProgress,
  box: __apex.race.world.pitBoxDistance,
  blend: __apex.race.pitCamBlend,
  y: __apex.race.camera.position.y,
  tyre: __apex.race.player.tyreLife
})));
await page.screenshot({ path: '/tmp/opencode/shots/leaving-box.jpg', type: 'jpeg', quality: 78 });
await page.waitForFunction(() => window.__apex.race.pitCamBlend < 0.06, null, { timeout: 30000 });
console.log('released', await page.evaluate(() => ({
  phase: __apex.race.pit.phase,
  route: __apex.race.pit.routeProgress,
  blend: __apex.race.pitCamBlend,
  y: __apex.race.camera.position.y,
  mode: __apex.race.cameraMode
})));
await page.screenshot({ path: '/tmp/opencode/shots/after-release.jpg', type: 'jpeg', quality: 78 });
await browser.close();

